## Crafting/cooking/stonecutting recipe tables.
## Generated by gen_recipes.nim from upstream/assets/datapack/data/minecraft/recipe/*.json
## - do not edit by hand.
## Skipped recipe types this pass (counts): minecraft:crafting_special_bannerduplicate=16, minecraft:crafting_transmute=33, minecraft:smithing_trim=18, minecraft:crafting_special_bookcloning=1, minecraft:crafting_decorated_pot=1, minecraft:crafting_special_firework_rocket=1, minecraft:crafting_special_firework_star=1, minecraft:crafting_special_firework_star_fade=1, minecraft:crafting_dye=6, minecraft:crafting_special_mapextending=1, minecraft:smithing_transform=12, minecraft:crafting_special_repairitem=1, minecraft:crafting_special_shielddecoration=1, minecraft:crafting_imbue=1

type
  RecipeCategory* = enum
    rcEquipment, rcBuilding, rcRedstone, rcMisc, rcFood, rcBlocks

  RecipeIngredientKind* = enum
    rikSimple, rikTagged, rikOneOf

  RecipeIngredient* = object
    case kind*: RecipeIngredientKind
    of rikSimple, rikTagged:
      name*: string
    of rikOneOf:
      options*: seq[string]

  RecipeResult* = object
    id*: string
    count*: uint8

  ShapedRecipe* = object
    id*: string
    category*: RecipeCategory
    group*: string
    showNotification*: bool
    keyChars*: seq[char]
    keyIngredients*: seq[RecipeIngredient]
    pattern*: seq[string]
    result*: RecipeResult

  ShapelessRecipe* = object
    id*: string
    category*: RecipeCategory
    group*: string
    ingredients*: seq[RecipeIngredient]
    result*: RecipeResult

  CookingRecipeKind* = enum
    crkSmelting, crkBlasting, crkSmoking, crkCampfireCooking

  CookingRecipe* = object
    id*: string
    kind*: CookingRecipeKind
    category*: RecipeCategory
    group*: string
    ingredient*: RecipeIngredient
    cookingTime*: int32
    experience*: float32
    result*: RecipeResult

  StonecutterRecipe* = object
    id*: string
    group*: string
    ingredient*: RecipeIngredient
    result*: RecipeResult

proc matches*(ing: RecipeIngredient, itemName: string): bool =
  ## `itemName` should be the full `minecraft:xxx` registry key. Tag
  ## matching (`rikTagged`) can't be resolved here - no tag membership
  ## table is ported yet - so it always returns false; callers that
  ## need real tag matching must special-case `ing.kind == rikTagged`
  ## against a real tag registry once one exists.
  case ing.kind
  of rikSimple: ing.name == itemName
  of rikTagged: false
  of rikOneOf: itemName in ing.options

